window.__until = (fn, ms) => new Promise(res => { const t0 = Date.now(); (function tick() { let v = false; try { v = fn(); } catch (e) { v = false; } if (v) return res(true); if (Date.now() - t0 > (ms || 12000)) return res(false); setTimeout(tick, 120); })(); });
window.__idle = () => { const c = document.getElementById('booking-results'); return !!c && c.style.opacity === '' && c.style.pointerEvents === ''; };
window.__vis = (el) => { if (!el) return false; const r = el.getBoundingClientRect(); const cs = getComputedStyle(el); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none'; };
window.__tap = (sel, min) => { const els = Array.from(document.querySelectorAll(sel)).filter(window.__vis); if (!els.length) return 'none:' + sel; const bad = els.filter(e => { const r = e.getBoundingClientRect(); return r.height < (min || 40) || r.width < (min || 40); }); return bad.length ? 'small:' + sel + ':' + bad.map(e => Math.round(e.getBoundingClientRect().width) + 'x' + Math.round(e.getBoundingClientRect().height)).join(',') : true; };
window.__noH = () => document.documentElement.scrollWidth <= window.innerWidth + 1;
window.__hdr = () => { const h = document.querySelector('.admin-header'); if (!h) return 0; const b = h.getBoundingClientRect().bottom; return b > 0 && b < innerHeight / 2 ? b : 0; };
window.__inView = (el) => { if (!window.__vis(el)) return false; const r = el.getBoundingClientRect(); return r.left >= -1 && r.right <= innerWidth + 1 && r.bottom <= innerHeight + 1 && r.top >= window.__hdr() - 1; };
window.__listCount = () => { const p = (document.querySelector('#booking-results .pg-summary') || {}).textContent || ''; const m = p.replace(/,/g, '').match(/of\s+(\d+)/); return m ? +m[1] : document.querySelectorAll('#booking-results tr[data-focus]').length; };
window.__q = (k) => new URLSearchParams(location.search).get(k);
document.addEventListener('DOMContentLoaded', () => { const s = document.createElement('style'); s.textContent = '#rhAiNotice, #admin-pwa-banner { display: none !important; }'; document.head.appendChild(s); });
